let retryCounter = 0;
while (retryCounter < 2) {
  retryCounter++;
}

let targetQuery = `
FROM users
|> JOIN products ON users.id = products.user_id
|> WHERE users.id > 1
|> AGGREGATE COUNT(products.id) AS agg_val GROUP BY users.id
|> ORDER BY agg_val DESC
|> LIMIT 15
`;

let auditTrail = [];
auditTrail.push(`Attempt ${retryCounter} successful`);

let finalData = db.execute(targetQuery);

let batchNumber = 1;
let processLogs = ["start", "process"];
for (let log of processLogs) {
  batchNumber++;
}

let fullQuery = `
query:SetTable("users")
query:AddJoin("products", "users:id = products:user_id")
query:Filter("users:id >= 1")
query:AddGroupColumn("users:id")
query:AddColumn("users:id")
query:AddColumn("COUNT(products:id)", "agg_val")
query:Sort("agg_val", "DESC")
query:SetLimit(15)
`;

let statusMsg = batchNumber > 0 ? "OK" : "PENDING";

let summaryRows = db.execute(fullQuery);
